import json
import os
import shlex
import sys
from contextlib import contextmanager
from typing import IO, Any, Dict, Iterator, List, Optional, Protocol, runtime_checkable

if sys.platform == "win32":
    from subprocess import Popen

try:
    import click
except ImportError:
    sys.stderr.write(
        "It seems python-dotenv is not installed with cli option. \n"
        'Run pip install "python-dotenv[cli]" to fix this.'
    )
    sys.exit(1)

from .main import dotenv_values as _main_dotenv_values, set_key as _main_set_key, unset_key as _main_unset_key
from .version import __version__


@runtime_checkable
class EnvironmentManager(Protocol):
    """Protocol for environment management operations needed by CLI."""

    def dotenv_values(
        self,
        dotenv_path: Optional[str] = None,
        stream: Optional[IO[str]] = None,
        verbose: bool = False,
        interpolate: bool = True,
        encoding: Optional[str] = "utf-8",
    ) -> Dict[str, Optional[str]]: ...

    def set_key(
        self,
        dotenv_path: str,
        key_to_set: str,
        value_to_set: str,
        quote_mode: str = "always",
        export: bool = False,
        encoding: Optional[str] = "utf-8",
    ) -> tuple: ...

    def unset_key(
        self,
        dotenv_path: str,
        key_to_unset: str,
        quote_mode: str = "always",
        encoding: Optional[str] = "utf-8",
    ) -> tuple: ...


class MainEnvironmentManager:
    """Adapter wrapping main module functions for dependency injection."""

    def dotenv_values(
        self,
        dotenv_path: Optional[str] = None,
        stream: Optional[IO[str]] = None,
        verbose: bool = False,
        interpolate: bool = True,
        encoding: Optional[str] = "utf-8",
    ) -> Dict[str, Optional[str]]:
        return _main_dotenv_values(
            dotenv_path=dotenv_path,
            stream=stream,
            verbose=verbose,
            interpolate=interpolate,
            encoding=encoding,
        )

    def set_key(
        self,
        dotenv_path: str,
        key_to_set: str,
        value_to_set: str,
        quote_mode: str = "always",
        export: bool = False,
        encoding: Optional[str] = "utf-8",
    ) -> tuple:
        return _main_set_key(
            dotenv_path=dotenv_path,
            key_to_set=key_to_set,
            value_to_set=value_to_set,
            quote_mode=quote_mode,
            export=export,
            encoding=encoding,
        )

    def unset_key(
        self,
        dotenv_path: str,
        key_to_unset: str,
        quote_mode: str = "always",
        encoding: Optional[str] = "utf-8",
    ) -> tuple:
        return _main_unset_key(
            dotenv_path=dotenv_path,
            key_to_unset=key_to_unset,
            quote_mode=quote_mode,
            encoding=encoding,
        )


def get_default_env_manager() -> EnvironmentManager:
    """Return the default environment manager instance."""
    return MainEnvironmentManager()
